    if (message.subSector !== "") {
      writer.uint32(34).string(message.subSector);
    }
    if (message.cik !== "") {
      writer.uint32(42).string(message.cik);
    }
    if (message.indexInclusionDate !== undefined) {
      DateMessage.encode(message.indexInclusionDate, writer.uint32(50).fork()).join();
    }
    if (message.weight !== undefined) {
      Decimal.encode(message.weight, writer.uint32(58).fork()).join();
    }
